# 7. UPS topologies
def ups_row(y,title,blocks,acc):
    o=T(4,y+18,'','')+TL(4,y-4,title,'t-s t-b')
    x=4
    for i,(t,w) in enumerate(blocks):
        o+=B(x,y,w,30,t,'bxa' if i in acc else 'bx','t-s');x2=x+w
        if i<len(blocks)-1:o+=A(x2,y+15,x2+12,y+15)
        x=x2+12
    return o
